begin;
create or replace function public.process_recurring_transaction_rules(p_rule_limit int default 50,p_occurrences_per_rule int default 12) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$ declare r public.recurring_transaction_rules%rowtype;w public.wallets%rowtype;c public.categories%rowtype;n int:=0;made int:=0;k int;key text;begin for r in select * from public.recurring_transaction_rules where active and archived_at is null and next_due_at<=now() order by next_due_at for update skip locked limit least(greatest(p_rule_limit,1),100) loop if not pg_try_advisory_xact_lock(hashtext('recurring:'||r.id::text)) then continue;end if;select * into w from public.wallets where id=r.wallet_id and user_id=r.user_id and status='active' and deleted_at is null;select * into c from public.categories where id=r.category_id and user_id=r.user_id and status='active' and archived_at is null and type=r.type;if w.id is null or c.id is null then update public.recurring_transaction_rules set active=false,last_error='Wallet or category is no longer active.' where id=r.id;continue;end if;k:=0;while r.next_due_at<=now() and(r.end_date is null or(r.next_due_at at time zone r.timezone)::date<=r.end_date)and k<least(greatest(p_occurrences_per_rule,1),12) loop key:='recurring:'||r.id::text||':'||to_char(r.next_due_at at time zone 'UTC','YYYYMMDD"T"HH24MISS"Z"');insert into public.transactions(user_id,wallet_id,category_id,type,amount,currency,description,note,occurred_at,status,source,idempotency_key,external_metadata) values(r.user_id,w.id,c.id,r.type::text::public.transaction_type,r.amount,w.currency,coalesce(nullif(r.note,''),'Recurring transaction'),nullif(r.note,''),r.next_due_at,'completed','recurring',key,jsonb_build_object('recurring_rule_id',r.id::text,'scheduled_occurrence',r.next_due_at)) on conflict(user_id,source,idempotency_key) where deleted_at is null do nothing;if found then made:=made+1;end if;r.next_due_at:=public.recurring_next(r);k:=k+1;end loop;if r.end_date is not null and(r.next_due_at at time zone r.timezone)::date>r.end_date then r.active:=false;end if;update public.recurring_transaction_rules set next_due_at=r.next_due_at,active=r.active where id=r.id;n:=n+1;end loop;return jsonb_build_object('processed_rules',n,'created_transactions',made,'catch_up_limit_per_rule',12);end $$;
commit;
